use std::{collections::BTreeMap,fs};fn main(){let s=fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();let mut r:BTreeMap<(String,String,String),Vec<f64>>=BTreeMap::new();for l in s.lines().skip(1){let v:Vec<_>=l.split('\t').collect();if v[8]=="NA"{continue}r.entry((v[0].into(),v[3].into(),v[4].into())).or_default().push(v[8].parse().unwrap())}for((g,m,n),v)in r{if ["redc","inv"].contains(&n.as_str()){let lo=v.iter().copied().fold(f64::INFINITY,f64::min);let hi=v.iter().copied().fold(0.0,f64::max);println!("g={g} modulus={m} counter={n} optimized_folded_over_pencil={lo:.6}..{hi:.6}")}}}
